373	function humanAge(seconds: number): string {
374	  if (seconds < 3600) return `${Math.max(1, Math.round(seconds / 60))}m`;
375	  if (seconds < 86400) return `${Math.round(seconds / 3600)}h`;
376	  return `${Math.round(seconds / 86400)}d`;
