418	/** Removes one worktree (and its branch) after the safety checks; returns a one-line report or throws. */
419	export function removeOne(ctx: WorktreeContext, token: string, options: RemoveOptions): string {
420	  const repo = openRepo(ctx.cwd);
421	  const registry = loadRegistry(repo);
422	  const entry = findEntry(repo, token, ctx.home);
423	  const label = entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path);
424	  if (entry.isMain) throw new WorktreeError("the main worktree cannot be removed");
425	  if (currentEntry(repo) === entry) throw new WorktreeError("you are inside this worktree; run the command from another directory");
426	  if (entry.locked) throw new WorktreeError("the worktree is locked; unlock it with `git worktree unlock` first");
427	  if (kindOf(repo, entry, registry) === "task" && !options.force) {
428	    throw new WorktreeError("this worktree belongs to a speculative run (/worktree discard); use --force to remove it anyway");
429	  }
430	
431	  const dropFromRegistry = () => updateRegistry(repo.commonDir, (reg) => { reg.worktrees = reg.worktrees.filter((item) => item.path !== entry.path); });
432	  const target = options.target ?? defaultBranch(repo);
433	  const targetSha = target ? resolveBranchCommit(repo, target) : undefined;
434	  const integrated = entry.head && targetSha ? integratedReason(repo, entry.head, targetSha) : null;
435	  if (!integrated && !options.deleteUnmerged) {
436	    throw new WorktreeError(`${entry.branch ? "branch" : "HEAD"} is not merged into ${target ? shownBranch(target) : "the default branch"}; merge it, or pass --delete-unmerged to discard its commits`);
437	  }
438	
439	  // The lock is taken before anything is deleted and held through the branch and registry bookkeeping, so a
440	  // concurrent `switch` (which holds it across its checkout) either finishes first or waits; a lock that cannot be
441	  // had fails here with the worktree, branch and registry untouched.
442	  let branchNote = "";
443	  let guardBranch = "";
444	  let guardHead = "";
445	  removeSeams.beforeLock?.(entry);
446	  withWorktreeLock(repo.commonDir, () => {
447	    // What was read before waiting for the lock may be out of date: another remover can have dropped this stale
448	    // registration and a `switch` recreated the path. Anything that differs from what was checked is not removed.
449	    const fresh = openRepo(repo.cwd).entries.find((candidate) => candidate.path === entry.path);
450	    if (!fresh) {
451	      dropFromRegistry();
452	      branchNote = " (it was already gone)";
453	      return;
454	    }
455	    if (fresh.prunable !== entry.prunable || fresh.head !== entry.head || fresh.branch !== entry.branch || fresh.locked) {
456	      throw new WorktreeError("the worktree changed while this command waited for the lock; nothing was removed. Run the command again");
457	    }
458	    if (entry.prunable) {
459	      // Only this registration goes: a bare `worktree prune` would drop every stale worktree and leave their
460	      // registry entries behind. `remove --force` accepts a missing directory and touches one admin entry.
461	      git(repo.cwd, ["worktree", "remove", "--force", "--end-of-options", entry.path]);
462	    } else {
463	      const before = verifiedWorktreeDir(repo, entry);
464	      if (!options.force) {
465	        const dirty = statusOf(entry.path, { ignored: true, ignoreSubmodules: "none" });
466	        if (dirty.total + (options.discardIgnored ? 0 : dirty.ignored) > 0) {
467	          throw new WorktreeError(`worktree has ${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked and ${dirty.ignored} ignored path(s); commit or clean them, or pass --force`);
468	        }
469	      }
470	      removeSeams.beforeRemove?.(entry);
471	      // A commit made here since the integration check (another session's `/commit`, an editor) must not be lost with
472	      // the directory: on a detached HEAD nothing else would keep it. A moved HEAD is checked again, or nothing is removed.
473	      const headNow = git(entry.path, ["rev-parse", "--verify", "HEAD"], { allowFailure: true }).stdout.trim();
474	      if (headNow && headNow !== entry.head) {
475	        if (!targetSha || !integratedReason(repo, headNow, targetSha)) {
476	          throw new WorktreeError("HEAD changed while the worktree was being checked and the new commit is not merged; nothing was removed. Run the command again");
477	        }
478	        entry.head = headNow;
479	      }
480	      // The directory must still be the one that was inspected: a swap for a link or another tree is refused.
481	      const after = identityOf(entry.path);
482	      if (!after || after.dev !== before.dev || after.ino !== before.ino) throw new WorktreeError("the worktree directory changed while it was being checked; nothing was removed");
