488	        // The commit the guard must protect is the one verified above, never one read after the switch: a commit that
489	        // lands in between would otherwise be adopted as "expected" and the branch deleted over it.
490	        guardHead = entry.head;
491	        // A guard branch that already exists was left by an interrupted attempt (or is someone's branch with that name).
492	        // It is never reused, moved or deleted: the user decides, before anything here is changed.
493	        const existing = git(repo.cwd, ["rev-parse", "--verify", "--quiet", "--end-of-options", `refs/heads/${guardBranch}`], { allowFailure: true });
494	        if (existing.status === 0) {
