499	        }
500	        removeSeams.beforeGuardSwitch?.(entry);
501	        const switched = git(entry.path, ["switch", "-c", guardBranch, "--end-of-options"], { allowFailure: true });
502	        if (switched.status !== 0) {
503	          guardBranch = "";
504	          throw new WorktreeError("could not protect the detached HEAD before removing it; nothing was removed");
505	        }
506	        removeSeams.afterGuardSwitch?.(entry);
507	        const nowHead = git(entry.path, ["rev-parse", "--verify", "HEAD"]).stdout.trim();
508	        // `git switch` is not atomic with a concurrent `git commit`: a commit can be written to the HEAD reflog while HEAD
509	        // ends up back at the checked commit. The reflog entry before the switch must be that commit too.
510	        const before = git(entry.path, ["rev-parse", "--verify", "--quiet", "HEAD@{1}"], { allowFailure: true });
511	        const reflogMismatch = before.status === 0 && before.stdout.trim() !== guardHead;
512	        if (nowHead !== guardHead || reflogMismatch) {
513	          const name = guardBranch;
514	          guardBranch = ""; // kept: it now holds the commit that landed
515	          throw new WorktreeError(`a commit landed while the detached HEAD was being protected (HEAD or its reflog moved); it is kept on the branch ${name} in ${shownPath(ctx.home, entry.path)}, with its reflog, and nothing was removed. Merge or delete that branch, then run the command again`);
516	        }
517	      }
518	      try {
519	        removeSeams.beforeGitRemove?.(entry);
520	        // `worktree remove` runs `git status` in the worktree and re-reads its `.git` pointer: verify it once more first.
521	        const unsafe = nestedRepositoryReason(entry.path);
522	        if (unsafe) throw new UntrustedCheckoutError(entry.path, unsafe, ["worktree", "remove"]);
523	        git(repo.cwd, ["worktree", "remove", ...(options.force ? ["--force"] : []), "--end-of-options", entry.path]);
524	      } catch (err) {
525	        // Git refused (an initialised submodule, a file that appeared): the worktree stays, so put it back on its
526	        // detached HEAD and drop the guard branch (unless a commit already moved it, then it is the only reference).
527	        if (guardBranch) {
528	          const back = git(entry.path, ["switch", "--detach", "--end-of-options", guardBranch], { allowFailure: true });
529	          if (back.status === 0) {
530	            deleteBranchAt(repo, guardBranch, git(entry.path, ["rev-parse", "--verify", "HEAD"]).stdout.trim());
531	          } else {
532	            throw new WorktreeError(`${(err as Error).message}; could not restore the detached HEAD, so ${shownPath(ctx.home, entry.path)} stays on the temporary branch ${guardBranch} (nothing is lost). To undo: git -C <that path> switch --detach, then git branch -D ${guardBranch}. Do that before running the command again, because a retry refuses while the branch exists`);
533	          }
534	        }
535	        throw err;
536	      }
537	    }
538	
539	    if (guardBranch) {
540	      branchNote = deleteBranchAt(repo, guardBranch, guardHead)
541	        ? ""
542	        : `; a commit landed after the last check and is kept on the branch ${guardBranch}`;
543	    }
544	    if (entry.branch && entry.branch !== target) {
545	      removeSeams.beforeBranchDeletion?.(entry);
546	      const stillCheckedOut = listAfter(repo).some((other) => other.branch === entry.branch);
547	      if (!stillCheckedOut) {
548	        // Only the commit that passed the integration check may be deleted. A commit made by another session in the
549	        // meantime (its `/commit`, for example) moves the branch, and `branch -D` would make it unreachable.
550	        branchNote = deleteBranchAt(repo, entry.branch, entry.head) ? " and deleted its branch" : "; its branch moved after it was checked and was kept";
551	      }
552	    }
553	    dropFromRegistry();
554	  });
555	  return `Removed worktree ${label}${branchNote}`;
556	}
