587	/** The worktree directory must be a real directory (not a link) whose `.git` file points into this repository. */
588	function verifiedWorktreeDir(repo: Repo, entry: WorktreeEntry): { dev: number; ino: number } {
589	  const before = identityOf(entry.path);
590	  const stat = fs.lstatSync(entry.path);
591	  if (!before || stat.isSymbolicLink() || !stat.isDirectory()) throw new WorktreeError("the worktree path is not a plain directory; refusing to remove it");
592	  const dotGit = path.join(entry.path, ".git");
593	  const content = readSmallFile(dotGit, MAX_POINTER_BYTES); // the agent controls this path: no blocking or unbounded read
594	  if (content === undefined) throw new WorktreeError("the worktree has no plain .git file; refusing to remove it");
595	  const pointer = parseGitfilePointer(content); // as Git reads it: nothing trimmed
596	  // The pointer may be absolute or, with `worktree.useRelativePaths`, relative to the worktree directory. Either way
597	  // its canonical location must be an entry under this repository's common directory.
598	  const admin = pointer === undefined ? "" : normalizedPath(path.resolve(entry.path, pointer));
599	  if (!admin || !admin.startsWith(path.join(normalizedPath(repo.commonDir), "worktrees") + path.sep)) {
600	    throw new WorktreeError("the worktree does not belong to this repository's common directory; refusing to remove it");
601	  }
602	  // The admin directory must point back at this very `.git` file. A pointer into a sibling worktree's admin directory
603	  // is inside the common directory too, but removing through it would act on the sibling's registration.
604	  let back = "";
605	  try { back = fs.readFileSync(path.join(admin, "gitdir"), "utf8").trim(); } catch { /* checked below */ }
606	  if (!back || normalizedPath(path.resolve(admin, back)) !== normalizedPath(dotGit)) {
607	    throw new WorktreeError("the worktree's administrative directory does not point back at it; refusing to remove it");
608	  }
609	  return { dev: before.dev, ino: before.ino };
610	}
