  const record = this.readStoredRecord(taskId)!;
  // Schema version check (fails closed on unsupported future versions) is performed before reading any messages.
  // Migrate legacy session file if necessary with pre-migration backup; publication below creates the backup first.
  const state: DurableTaskState = this.migrateIfLegacy(record.parsed, taskId);
  this.normalizeWorktreeBinding(state, taskId, record);

  // Verify task identity binding
  if (state.taskId && taskId && state.taskId !== taskId && state.sessionId !== taskId) {
    throw new TaskIdentityMismatchError(taskId, state.taskId);
  }

  // Verify workspace binding if expectedWorkspace provided
  let selectedPaths = workspacePaths;
  let normalizedLegacyWorkspace = false;
  if (expectedWorkspace && state.workspacePath) {
    const expectedIdentity = WorkspacePath.fromSelectedWorkspace(path.resolve(expectedWorkspace));
    const normExpected = expectedIdentity.value;
    const normActual = path.resolve(state.workspacePath);
    if (normExpected !== normActual) {
      // Earlier builds recorded the active speculative worktree as the task's workspace identity.
      // Normalise such a record only when its own binding proves the expected root owns that exact
      // managed worktree; every other mismatch stays fail-closed. The load path persists the
      // normalised record below (workspacePath changes are protected identity fields).
      const binding = state.worktreeBinding;
      const bindingPath = binding?.worktreePath ? path.resolve(binding.worktreePath) : undefined;
      if (
        state.taskId !== taskId ||
        bindingPath !== normActual ||
        !binding ||
        !(isManagedWorktreePath(expectedIdentity, normActual, taskId, binding) || isNamedWorktreePath(expectedIdentity, normActual, binding))
      ) {
        throw new WorkspaceIdentityMismatchError(normExpected, normActual);
      }
      state.workspacePath = normExpected;
      state.workspace = normExpected;
      normalizedLegacyWorkspace = true;
    }
    selectedPaths = [...workspacePaths, expectedIdentity];
  }

  state.messages = this.storedMessages(taskId, record);
  // Internal synchronous read-modify-save transactions classify the complete
  // state once, after mutation and before publication/return. Public recovery
  // reads always protect here, including migration of older plaintext state.
  if (!protectOnLoad) return state;

  if (!this.durable) return state;
  this.stateManager.saveTaskState(state);
  return state;
}

public async recoverFromTaskState(
  taskId: string,
  options: TaskRecoveryOptions = {}
): Promise<TaskRecoveryResult> {
  const recoveryResult = this.stateManager.recoverTaskState(taskId, {
    expectedWorkspace: this.config.workspace,
    candidateTracker: this.candidateTracker,
    worktreeManager: this.worktreeManager,
    authorityEngine: this.authorityEngine,
    currentConfig: {
      readOnly: this.config.readOnly,
      fullAccess: this.config.fullAccess,
    },
    ...options,
  });

  const state = recoveryResult.state;
  this.currentTaskId = state.taskId;
  // Switch to the recorded worktree before restoring the recovered envelope: setWorkspace() resets the
  // conversation, so restoring first would silently drop the messages, objective, archive and findings that
  // recovery just read from disk. The binding is authoritative only after the state manager validated it.
  if (state.worktreeBinding && recoveryResult.worktreeStatus === "consistent") {
    this.activeWorktree = {
      taskId: state.worktreeBinding.taskId,
      worktreePath: state.worktreeBinding.worktreePath,
      branch: state.worktreeBinding.branch,
      kind: state.worktreeBinding.kind ?? "task",
    };
    // Remember the checkout the task was resumed from so /merge and /discard can return there.
    this.originalWorkspace = this.originalWorkspace ?? this.primaryWorkspacePathIdentity.value;
    this.switchWorktreeWorkspace(state.worktreeBinding.worktreePath);
  }
  this.activePlan = state.activePlan || [];
  this.messages = withSkillNoteProvenance(state.messages || []);
  this.restoreFindings(state.findings);

